"""Rolling median over a fixed window."""
import bisect
from collections import deque


class RollingMedian:
    def __init__(self, window):
        self.window = window
        self.buf = deque()
        self.sorted = []

    def push(self, x):
        if len(self.buf) == self.window:
            old = self.buf.popleft()
            i = bisect.bisect_left(self.sorted, old)
            self.sorted.pop(i)
        self.buf.append(x)
        bisect.insort(self.sorted, x)

    def value(self):
        n = len(self.sorted)
        if n == 0:
            return None
        mid = n // 2
        if n % 2:
            return self.sorted[mid]
        return (self.sorted[mid - 1] + self.sorted[mid]) / 2
